#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024
#define MAX_NORM_LEN MAX_INPUT_LEN

int main(int argc, char *argv[])
{
    const char *msg_pal = "PALINDROME";
    const char *msg_not = "NOT_PALINDROME";
    const char *msg_long = "TOO_LONG";

    const char *input = "";
    if (argc > 1) {
        input = argv[1];
        if ((size_t)strlen(input) > MAX_INPUT_LEN) {
            puts(msg_long);
            return 0;
        }
    }

    char norm[MAX_NORM_LEN + 1];
    size_t n = 0;
    for (size_t i = 0; input[i] != '\0' && n < MAX_NORM_LEN; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    int is_pal = 1;
    for (size_t i = 0, j = n ? n - 1 : 0; i < j; ++i, --j) {
        if (norm[i] != norm[j]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? msg_pal : msg_not);
    return 0;
}
